import sys
from typing import List

def min_cost_to_win_tournament(n: int, a: List[int]) -> int:
    # Find the index of the friend
    friend_index = a.index(-1)

    # Initialize the memoization table
    memo = [[float('inf')] * n for _ in range(n)]

    def dp(i, j):
        if i == j:
            return 0
        if memo[i][j] != float('inf'):
            return memo[i][j]

        mid = (i + j) // 2
        left_min = float('inf')
        right_min = float('inf')

        for k in range(i, mid + 1):
            left_min = min(left_min, max(dp(i, k - 1), dp(k + 1, mid)))

        for k in range(mid + 1, j + 1):
            right_min = min(right_min, max(dp(mid + 1, k - 1), dp(k + 1, j)))

        if friend_index >= i and friend_index <= mid:
            memo[i][j] = min(memo[i][j], left_min)
        else:
            memo[i][j] = min(memo[i][j], left_min + a[mid])

        if friend_index >= mid + 1 and friend_index <= j:
            memo[i][j] = min(memo[i][j], right_min)
        else:
            memo[i][j] = min(memo[i][j], right_min + a[mid])

        return memo[i][j]

    return dp(0, n - 1)

