def min_bribe_cost(n, a):
    def helper(boxers, cost):
        if len(boxers) == 1:
            return cost
        weakest = min(boxers)
        index = boxers.index(weakest)
        if a[index] != -1:
            cost += a[index]
        new_boxers = [boxers[i] for i in range(len(boxers)) if i != index]
        return helper(new_boxers, cost)

    boxers = list(range(1, n + 1))
    return helper(boxers, 0)

