import sys
from typing import List

def min_cost_to_win_tournament(n: int, a: List[int]) -> int:
    # Find the index of the friend
    friend_index = a.index(-1)

    # Initialize memoization table
    memo = [[[-1] * 2 for _ in range(n)] for _ in range(n)]

    def dp(i: int, j: int, turn: int) -> int:
        if i == j:
            return 0 if turn == 0 else float('inf')

        if memo[i][j][turn] != -1:
            return memo[i][j][turn]

        if turn == 0:
            # Your friend's turn to minimize cost
            min_cost = float('inf')
            for k in range(i + 1, j):
                cost = max(dp(i, k, 1), dp(k, j, 1))
                if a[k] < a[j]:
                    cost += a[j]
                min_cost = min(min_cost, cost)
            memo[i][j][turn] = min_cost
        else:
            # Opponent's turn to maximize cost
            max_cost = 0
            for k in range(i + 1, j):
                cost = max(dp(i, k, 0), dp(k, j, 0))
                if a[k] > a[j]:
                    cost += a[j]
                max_cost = max(max_cost, cost)
            memo[i][j][turn] = max_cost

        return memo[i][j][turn]

    return dp(0, n - 1, 0)

